//! The kuna-facing option table of the JVM engine, generated by `build.rs`
//! from `options.toml`: one row per exposed Vineflower option, named
//! `jvm_<long name>` (Vineflower's long and short names are aliases), plus
//! the kuna-side `jvm_siblings` and `jvm_plugins`; and the keys kuna's driver
//! owns. A row of a bundled plugin's option names the plugin's key.
//!
//! [`resolve`] turns a name and a value as a user writes them into the
//! Vineflower key and value the engine takes.

use crate::context_source::java_parse_int;
use crate::rt::try_catch;

/// One option row; the fields are those of a `[[settable]]` row of
/// `kuna-decomp/phases.toml`, plus Vineflower's names.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub struct JvmOption {
    pub option: &'static str,
    /// Vineflower's long name; empty for an option of kuna's own.
    pub vineflower: &'static str,
    /// Vineflower's three-letter name, if it has one.
    pub short: &'static str,
    pub aliases: &'static [&'static str],
    pub values: &'static str,
    pub default: &'static str,
    pub destructive: bool,
    pub phase: &'static str,
    pub subphase: &'static str,
    pub strength: &'static str,
    pub rewind: &'static str,
    pub issue: &'static str,
    pub summary: &'static str,
    pub use_when: &'static str,
    pub example: &'static str,
    pub source_decompiler: &'static str,
    pub inspiration: &'static str,
    pub change_kind: &'static str,
    pub tier: &'static str,
    pub symptoms: &'static str,
}

/// A Vineflower key kuna sets itself; `kuna` says what sets it.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub struct DriverOwned {
    pub vineflower: &'static str,
    pub kuna: &'static str,
}

include!(concat!(env!("OUT_DIR"), "/jvm_options.rs"));

/// What values an option takes.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum ValueKind {
    /// `on|off`, also `1|0|true|false`.
    Bool,
    /// A decimal integer.
    Int,
    /// Any text.
    Text,
    /// A Java regular expression.
    Regex,
    /// `on|off|current|<path>` (`include-runtime`).
    Runtime,
}

impl JvmOption {
    pub fn kind(&self) -> ValueKind {
        match self.values {
            "on|off" => ValueKind::Bool,
            "<n>" => ValueKind::Int,
            "<regex>" => ValueKind::Regex,
            "on|off|current|<path>" => ValueKind::Runtime,
            _ => ValueKind::Text,
        }
    }

    /// Whether the row is one of kuna's own (no Vineflower key).
    pub fn is_kuna(&self) -> bool {
        self.vineflower.is_empty()
    }

    /// The symptoms as a list.
    pub fn symptom_list(&self) -> Vec<&'static str> {
        self.symptoms.split('|').collect()
    }
}

/// Every option row, in table order.
pub fn rows() -> &'static [JvmOption] {
    JVM_OPTION_TABLE
}

/// The keys kuna's driver sets itself.
pub fn driver_owned() -> &'static [DriverOwned] {
    JVM_DRIVER_OWNED
}

/// The row named `name` (its `jvm_` name or an alias).
pub fn find(name: &str) -> Option<&'static JvmOption> {
    JVM_OPTION_TABLE
        .iter()
        .find(|r| r.option == name || r.aliases.contains(&name))
}

/// The Vineflower key and value for option `name` set to `value`. For a
/// kuna-side option (`jvm_siblings`, `jvm_plugins`) the key is the option's
/// own name; `Fernflower::new` takes `jvm_plugins` itself.
/// Booleans come back as `1`/`0`, integers in decimal, `include-runtime` as
/// `1` (on, true), `0` (off, false), `current` or the given path.
pub fn resolve(name: &str, value: &str) -> Result<(&'static str, String), String> {
    let Some(row) = find(name) else {
        if let Some(owned) = JVM_DRIVER_OWNED.iter().find(|d| {
            d.vineflower == name || format!("jvm_{}", d.vineflower.replace('-', "_")) == name
        }) {
            return Err(format!(
                "JVM option {name} is set by kuna itself ({})",
                owned.kuna
            ));
        }
        return Err(match suggest(name) {
            Some(s) => format!("unknown JVM option {name}; did you mean {s}?"),
            None => format!("unknown JVM option {name} (kuna catalog --engine jvm lists them)"),
        });
    };
    let key = if row.is_kuna() {
        row.option
    } else {
        row.vineflower
    };
    let bad = |expected: &str| {
        Err(format!(
            "{}: invalid value {value:?} (expected {expected})",
            row.option
        ))
    };
    let resolved = match row.kind() {
        ValueKind::Bool => match boolean(value) {
            Some(true) => "1".to_string(),
            Some(false) => "0".to_string(),
            None => return bad("on|off"),
        },
        ValueKind::Int => match java_parse_int(value.trim()) {
            Some(n) => n.to_string(),
            None => return bad("an integer"),
        },
        ValueKind::Regex => {
            let compiled = try_catch(|| {
                crate::classes_processor::java_regex::JavaPattern::compile(value);
            });
            if let Err(e) = compiled {
                return Err(format!(
                    "{}: invalid regular expression {value:?}: {}",
                    row.option, e.message
                ));
            }
            value.to_string()
        }
        ValueKind::Runtime => {
            if value.eq_ignore_ascii_case("current") {
                "current".to_string()
            } else {
                match boolean(value) {
                    Some(true) => "1".to_string(),
                    Some(false) => "0".to_string(),
                    None if value.is_empty() => String::new(),
                    None => value.to_string(),
                }
            }
        }
        ValueKind::Text => value.to_string(),
    };
    Ok((key, resolved))
}

fn boolean(value: &str) -> Option<bool> {
    match value.to_ascii_lowercase().as_str() {
        "on" | "1" | "true" => Some(true),
        "off" | "0" | "false" => Some(false),
        _ => None,
    }
}

/// The nearest option name or alias, if one is close.
pub fn suggest(name: &str) -> Option<&'static str> {
    let candidates = JVM_OPTION_TABLE
        .iter()
        .flat_map(|r| std::iter::once(r.option).chain(r.aliases.iter().copied()));
    let lowered = name.to_ascii_lowercase().replace('-', "_");
    candidates
        .map(|c| {
            (
                distance(&lowered, &c.to_ascii_lowercase().replace('-', "_")),
                c,
            )
        })
        .filter(|&(d, c)| d <= (c.len() / 3).max(2))
        .min_by_key(|&(d, c)| (d, c))
        .map(|(_, c)| c)
}

fn distance(a: &str, b: &str) -> usize {
    let a: Vec<char> = a.chars().collect();
    let b: Vec<char> = b.chars().collect();
    let mut row: Vec<usize> = (0..=b.len()).collect();
    for (i, ca) in a.iter().enumerate() {
        let mut previous = row[0];
        row[0] = i + 1;
        for (j, cb) in b.iter().enumerate() {
            let substitute = previous + usize::from(ca != cb);
            previous = row[j + 1];
            row[j + 1] = substitute.min(row[j] + 1).min(previous + 1);
        }
    }
    row[b.len()]
}
